import hashlib
import os

def compute_md5_hash(file_path):
    md5 = hashlib.md5()

    if not os.path.isfile(file_path):
        return None

    with open(file_path, 'rb') as f:
        while chunk := f.read(4096): 
            md5.update(chunk)

    return md5.hexdigest().upper()
