enum CompilerError {
    CompileFailed(std::io::Error),
    OtherError(EarlyError<std::io::Error>),
}

#[catch_with_exit_code]
impl std::fmt::Debug for CompilerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CompilerError::CompileFailed(err) => f.debug_tuple(""CompilerError"").field(&err).finish(),
            CompilerError::OtherError(err) => f.debug_tuple(""CompilerError"").field(&err).finish(),
        }
    }
