from Crypto.Cipher import DES3
from Crypto.Util.Padding import unpad

def decrypt_message(filename: str, encryption_key: str) -> bytes:
    with open(filename, ""rb"") as file:
        encrypted_data = file.read()

    key = encryption_key.encode(""utf-8"")
    iv = b'\0' * 8  # default initialization vector

    cipher = DES3.new(key, DES3.MODE_CBC, iv)
    decrypted_data = unpad(cipher.decrypt(encrypted_data), block_size=8)

    return base64.b64decode(decrypted_message)

def decrypt_and_hash(filename: str,
                     encryption_key: str,
                     command: str) -> str:
    if command == ""md5"":
        hasher = hashlib.md5()
    elif command == ""sha1"":
        hasher = hashlib.sha1()
    elif command == ""sha256"":
        hasher = hashlib.sha256()
    else:
        raise ValueError(""Invalid hashing algorithm"")

    with open(filename, ""rb"") as file:
        chunk_size = 4096
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hasher.update(data)

    return hasher.hexdigest()

