import json
from abc import ABCMeta, abstractmethod

class JSONHandler(metaclass=ABCMeta):
    @abstractmethod
    def to_json(self):
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_data):
        pass


class JSONRegistry:
    registry = {}

    @classmethod
    def add_factory(cls, id, factory):
        cls.registry[id] = factory

    @classmethod
    def get_factory(cls, id):
        return cls.registry.get(id)


class ObjectFactory(metaclass=ABCMeta):
    @abstractmethod
    def to_json(self):
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_data):
        pass


def object_factory_registry():
    registry = {}
    return registry


class JSONSerializable:
    def __init__(self, id):
        self.id = id

    def to_json(self):
        return {""id"": self.id}

    @classmethod
    def from_json(cls, json_data):
        obj = cls(json_data[""id""])
        return obj


class MyJSONHandler(JSONHandler):
    def to_json(self):
        pass

    @classmethod
    def from_json(cls, json_data):
        pass

# Usage:

registry = JSONRegistry()

class MySerializable(JSONSerializable):
    pass

registry.add_factory(""MySerializable"", lambda: MySerializable(None))

my_obj = registry.get_factory(""MySerializable"")().to_json()
