import random
import copy

def generate_random_list(min_value, max_value):
    return [random.randint(min_value, max_value) for _ in range(10)]

def bubble_sort(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

def check_sorted_list(original_list, sorted_list):
    if original_list == sorted_list:
        return ""The list is correct.""
    else:
        return ""The list is not correct.""

min_value = 1
