import hashlib
import logging

class SecureHashGenerator:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        logging.basicConfig(filename='hash_log.txt', level=logging.INFO)

    def generate_hash(self, input_string, command):
        if not input_string:
            raise ValueError(""Input string cannot be null or empty."")

        hasher = {
            'md5': hashlib.md5(),
            'sha1': hashlib.sha1(),
            'sha256': hashlib.sha256()
        }[command]

        try:
            hasher.update(input_string.encode('utf-8'))
            self.logger.info(f""Input: {input_string}"")
            return hasher.hexdigest()
        except Exception as e:
            self.logger.error(f""Error: {e}"")
