import json
from abc import ABC, abstractmethod

class JSONManager:
    _registry = {}

    def register_factory(self, id: str, factory):
        self._registry[id] = factory

    def from_json(self, json_string):
        obj = json.loads(json_string)
        return self._construct_object(obj)

    @abstractmethod
    class Object(ABC):
        @abstractmethod
        def to_json(self):
            pass

    def _construct_object(self, obj):
        if 'id' in obj:
            id = obj['id']
            if id in self._registry:
                factory = self._registry[id]
                return factory()
            else:
                raise ValueError(f""Unknown ID: {id}"")
        else:
            raise ValueError(""No ID found"")

