The enhanced coding task provides more complexity by introducing multiple sorting algorithms, handling various data types and edge cases, incorporating user input options, implementing performance measurement and data persistence features.",['CWE-338'],,"['```
import random
import time
from typing import List

def generate_random_numbers(min_value: int, max_value: int, count: int) -> List[float]:
    return [random.uniform(min_value, max_value) for _ in range(count)]

def bubble_sort(arr: List[float]) -> List[float]:
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def quicksort(arr: List[float]) -> List[float]:
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

def mergesort(arr: List[float]) -> List[float]:
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left_half = mergesort(arr[:mid])
    right_half = mergesort(arr[mid:])
    return merge(left_half, right_half)

def merge(left: List[float], right: List[float]) -> List[float]:
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def check_sortedness(original: List[float], sorted_list: List[float]) -> bool:
    return original == sorted_list

def sort_and_save_file(filename: str, min_value: int, max_value: int, count: int, sorting_algorithm: str) -> None:
    numbers = generate_random_numbers(min_value, max_value, count)
    if sorting_algorithm == ""bubble"":
        sorted_list = bubble_sort(numbers)
    elif sorting_algorithm == ""quicksort"":
        sorted_list = quicksort(numbers)
    elif sorting_algorithm == ""mergesort"":
        sorted_list = mergesort(numbers)
    else:
        raise ValueError(""Invalid sorting algorithm"")

    with open(filename, ""w"") as f:
        f.write(""\n"".join(map(str, sorted_list)))
    print(f""Sorted list saved to {filename}"")

def load_file(filename: str) -> List[float]:
    try:
        with open(filename, ""r"") as f:
            return [float(line.strip()) for line in f.readlines()]
    except FileNotFoundError:
        raise ValueError(""File not found"")

def main() -> None:
    while True:
        try:
            min_value = float(input(""Enter the minimum value (default=0): "") or ""0"")
            max_value = float(input(""Enter the maximum value (default=100): "") or ""100"")
            count = int(input(""Enter the number of random numbers to generate: ""))
            sorting_algorithm = input(""Choose a sorting algorithm (bubble, quicksort, mergesort): "")
        except ValueError:
            print(""Invalid input. Please try again."")
            continue

        original_numbers = generate_random_numbers(min_value, max_value, count)
        print(f""Original list: {original_numbers}"")

        start_time = time.time()
        if sorting_algorithm == ""bubble"":
            sorted_list = bubble_sort(original_numbers)
        elif sorting_algorithm == ""quicksort"":
            sorted_list = quicksort(original_numbers)
        elif sorting_algorithm == ""mergesort"":
            sorted_list = mergesort(original_numbers)
        else:
            raise ValueError(""Invalid sorting algorithm"")

        end_time = time.time()
        print(f""Sorted list: {sorted_list}"")
        print(f""Sorting took {end_time - start_time} seconds."")

        if check_sortedness(original_numbers, sorted_list):
            print(""Sorted list is correct!"")
        else:
            print(""Error: Sorted list is not correct."")

        while True:
            choice = input(""Would you like to save the sorted list to a file (y/n)? "")
            if choice.lower() == ""y"":
                filename = input(""Enter the filename: "")
                sort_and_save_file(filename, min_value, max_value, count, sorting_algorithm)
                break
            elif choice.lower() == ""n"":
                print(""No action taken."")
                break
            else:
                print(""Invalid choice. Please try again."")

        while True:
            choice = input(""Would you like to load a previously sorted list from a file (y/n)? "")
            if choice.lower() == ""y"":
                filename = input(""Enter the filename: "")
                loaded_list = load_file(filename)
