import csv
import pandas as pd

def analyze_user_activity(csv_file):
    try:
        df = pd.read_csv(csv_file)

        if df.empty:
            return ""File is empty. Please check the file contents.""

        activity_dict = {}
        for index, row in df.iterrows():
            user = row['user']
            activity = row['activity']
            time_spent = float(row['time_spent'])

            if user not in activity_dict:
                activity_dict[user] = {'work': [], 'leisure': [], 'personal': []}

            if pd.isna(time_spent):
                return ""File contains missing data. Please check the file contents.""

            if row['category'] == 'work':
                activity_dict[user]['work'].append((activity, time_spent))
            elif row['category'] in ['leisure', 'personal']:
                activity_dict[user][row['category']].append((activity, time_spent))

        for user in activity_dict:
            work_activities = [t[1] for t in activity_dict[user]['work']]
            leisure_activities = [t[1] for t in activity_dict[user]['leisure'] + activity_dict[user]['personal']]

            avg_work_time = sum(work_activities) / len(work_activities) if work_activities else 0
            avg_leisure_time = sum(leisure_activities) / len(leisure_activities) if leisure_activities else 0

            if avg_work_time > 0 and avg_leisure_time > 0:
                return ""Invalid input. Please specify a single category for each user.""

            activities_list = activity_dict[user]['work'] + activity_dict[user]['leisure'] + activity_dict[user]['personal']
            activities_list.sort(key=lambda x: x[1], reverse=True)

            top_5_users = {}
            for i in range(5):
                if not activities_list:
                    break
                activity = activities_list.pop()
                user_avg_time = (avg_work_time + avg_leisure_time) / 2
                top_5_users[user] = {'average_time': user_avg_time, 'activities': [t[0] for t in activities_list[:5]]}

        return {k: v for k, v in sorted(top_5_users.items(), key=lambda item: item[1]['average_time'], reverse=True)}
    except FileNotFoundError:
        return ""File not found. Please check the file path.""
