def fibonacci_dp(n):
    memo = {0: 0, 1: 1}
    for i in range(2, n+1):
        memo[i] = memo[i-1] + memo[i-2]
    return memo[n]

def fibonacci_matrix(n):
    if n <= 1:
        return n
    matrix = [[1, 1], [1, 0]]
    power(matrix, n - 1)
    return matrix[0][0]

def multiply(matrix_a, matrix_b):
    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                result[i][j] += matrix_a[i][k] * matrix_b[k][j]
    return result

def power(matrix, n):
    if n == 1:
        return matrix
    elif n % 2 == 0:
        half_power = power(matrix, n // 2)
        return multiply(half_power, half_power)
    else:
        half_power = power(matrix, n // 2)
        return multiply(multiply(half_power, half_power), [[1, 1], [1, 0]])

def test_fibonacci():
    for i in range(20):
        dp_value = fibonacci_dp(i)
        matrix_value = fibonacci_matrix(i)
        print(f""Fibonacci {i}: DP={dp_value}, Matrix={matrix_value}"")
        if i > 2:
            assert dp_value == matrix_value

def main():
    while True:
        print(""1. Calculate Fibonacci numbers"")
        print(""2. Test correctness of calculated values"")
        choice = input(""Enter your choice (1/2): "")
        if choice == ""1"":
            method = input(""Choose calculation method (DP/M): "")
            if method.upper() == ""DP"":
                n = int(input(""Enter the number for which you want to calculate the Fibonacci value: ""))
                try:
                    result = fibonacci_dp(n)
                    print(f""Fibonacci {n}: {result}"")
                except Exception as e:
                    print(f""Error: {e}"")
            elif method.upper() == ""M"":
                n = int(input(""Enter the number for which you want to calculate the Fibonacci value: ""))
                try:
                    result = fibonacci_matrix(n)
                    print(f""Fibonacci {n}: {result}"")
                except Exception as e:
                    print(f""Error: {e}"")
        elif choice == ""2"":
            test_fibonacci()
        else:
            print(""Invalid input. Please enter 1 or 2."")

if __name__ == ""__main__"":
    main()

# Testing and error handling
