class NFAPI_NetworkManager:
    def generatePDUs(self, numPDUs):
        pdus = []
        for _ in range(numPDUs):
            pdu_id = random.randint(1, 1000)
            while not (pdu_id >= 1 and pdu_id <= 1000):
                pdu_id = random.randint(1, 1000)
            status_code = random.randint(0, 999)
            timestamp = int(datetime.now().timestamp() * 1000)
            pdus.append({'id': pdu_id, 'status_code': status_code, 'timestamp': timestamp})
        return pdus

    def printPDUs(self, pdus):
        for pdu in pdus:
            print(f""PDU ID: {pdu['id']}, Status Code: {pdu['status_code']}, Timestamp: {pdu['timestamp']}"")

def main():
    manager = NFAPI_NetworkManager()
    ue_tags = []
    for _ in range(5):
        ue_tag = UE_InformationTag()
        ue_tag.setCRCFlag()
        ue_tags.append(ue_tag)

    pdus = manager.generatePDUs(len(ue_tags))
    manager.printPDUs(pdus)

if __name__ == ""__main__"":
    main()
