def collatz_sequence_dp(n):
    memo = {1: 0}

    def helper(k):
        if k not in memo:
            if k % 2 == 0:
                memo[k] = 1 + helper(k // 2)
            else:
                memo[k] = 1 + helper(3 * k + 1)
        return memo[k]

    return helper(n)


def collatz_sequence_optimized(n):
    result = 0
    while n > 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        result += 1
    return result


def test_collatz_sequences():
    for i in range(10):
        print(f""n: {i}, Dynamic Programming: {collatz_sequence_dp(i)}, Optimized Method: {collatz_sequence_optimized(i)}"")


class CollatzSequenceCalculator:
    def __init__(self):
        self.memo = {1: 0}

    def calculate_collatz_sequence(self, n, method=""dynamic""):
        if method == ""dynamic"":
            return collatz_sequence_dp(n)
        elif method == ""optimized"":
            return collatz_sequence_optimized(n)
        else:
            raise ValueError(""Invalid calculation method"")

    def test_collatz_sequences(self):
        for i in range(10):
            print(f""n: {i}, Dynamic Programming: {collatz_sequence_dp(i)}, Optimized Method: {collatz_sequence_optimized(i)}"")


def main():
    calculator = CollatzSequenceCalculator()

    while True:
        print(""\nCollatz Sequence Calculator"")
        print(""1. Calculate Collatz sequence value using dynamic programming"")
        print(""2. Calculate Collatz sequence value using optimized mathematical approach"")
        print(""3. Test the correctness of both calculation methods with various input values"")
        print(""4. Exit program\n"")

        choice = int(input(""Enter your choice: ""))

        if choice == 1:
            n = int(input(""Enter a number to calculate its Collatz sequence value: ""))
            start_time = time.time()
            result = calculator.calculate_collatz_sequence(n, method=""dynamic"")
            end_time = time.time()
            print(f""Collatz sequence value for {n} using dynamic programming: {result}"")
            print(f""Execution time: {end_time - start_time:.2f} seconds\n"")

        elif choice == 2:
            n = int(input(""Enter a number to calculate its Collatz sequence value: ""))
            start_time = time.time()
            result = calculator.calculate_collatz_sequence(n, method=""optimized"")
            end_time = time.time()
            print(f""Collatz sequence value for {n} using optimized mathematical approach: {result}"")
            print(f""Execution time: {end_time - start_time:.2f} seconds\n"")

        elif choice == 3:
            calculator.test_collatz_sequences()

        elif choice == 4:
            print(""Exiting program..."")
            break

        else:
            print(""Invalid choice. Please try again.\n"")


if __name__ == ""__main__"":
    main()
