```python
import random
import time
from datetime import datetime

def bubble_sort(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

def quicksort(lst):
    if len(lst) <= 1:
        return lst
    pivot = lst[len(lst)-1]
    left = [x for x in lst if x < pivot]
    middle = [x for x in lst if x == pivot]
    right = [x for x in lst if x > pivot]
    return quicksort(left) + middle + quicksort(right)

def mergesort(lst):
    if len(lst) <= 1:
        return lst
    mid = len(lst)//2
    left_half = lst[:mid]
    right_half = lst[mid:]
    return merge(mergesort(left_half), mergesort(right_half))

def merge(left, right):
    merged = []
    left_index = 0
    right_index = 0
    while left_index < len(left) and right_index < len(right):
        if left[left_index] <= right[right_index]:
            merged.append(left[left_index])
            left_index += 1
        else:
            merged.append(right[right_index])
            right_index += 1
    merged.extend(left[left_index:])
    merged.extend(right[right_index:])
    return merged

def generate_random_numbers(min_value, max_value, count):
    return [random.randint(min_value, max_value) for _ in range(count)]

def main():
    print(""Sorting Algorithm Options:"")
    print(""1. Bubble Sort"")
    print(""2. Quicksort"")
    print(""3. Mergesort"")

    algorithm_choice = input(""Choose an algorithm (1/2/3): "")

    if not algorithm_choice.isdigit() or int(algorithm_choice) < 1 or int(algorithm_choice) > 3:
        print(""Invalid choice. Defaulting to Bubble Sort."")
        algorithm_choice = ""1""

    min_value = float(input(""Enter the minimum value: ""))
    max_value = float(input(""Enter the maximum value: ""))
    count = int(input(""Enter the number of random numbers to generate: ""))

    if not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
        print(""Invalid input. Minimum and maximum values must be numbers."")
        return

    if min_value > max_value:
        print(""Invalid range. Minimum value cannot be greater than maximum value."")
        return

    try:
        random_numbers = generate_random_numbers(min_value, max_value, count)

        start_time = time.time()

        if algorithm_choice == ""1"":
            sorted_numbers = bubble_sort(random_numbers.copy())
        elif algorithm_choice == ""2"":
            sorted_numbers = quicksort(random_numbers.copy())
        else:
            sorted_numbers = mergesort(random_numbers.copy())

        end_time = time.time()

        print(f""Sorted numbers in ascending order: {sorted_numbers}"")

        if random_numbers != sorted_numbers:
            print(""Verification failed. The generated list is not the same as the sorted list."")
        else:
            print(""Verification passed. The generated list matches the sorted list."")

        average_time = (end_time - start_time) / 3
        print(f""Average time taken for sorting: {average_time} seconds"")

    except ValueError:
        print(""Error occurred while processing input values."")

def save_to_file(sorted_numbers):
    filename = datetime.now().strftime(""%Y%m%d%H%M%S"") + ""_sorted.txt""
    with open(filename, ""w"") as file:
        file.write(str(sorted_numbers))

def load_from_file():
    filename = input(""Enter the filename to load: "")

    try:
        with open(filename, ""r"") as file:
            sorted_numbers = eval(file.read())
            return sorted_numbers
    except FileNotFoundError:
        print(f""File {filename} not found."")
        return None
    except Exception as e:
        print(f""Error occurred while loading the file: {e}"")
        return None

def main_menu():
    print(""Sorting Options:"")
    print(""1. Generate and Sort Random Numbers"")
    print(""2. Load Sorted Numbers from a File"")

    choice = input(""Choose an option (1/2): "")

    if choice == ""1"":
        main()
    elif choice == ""2"":
        sorted_numbers = load_from_file()
        if sorted_numbers is not None:
            print(f""Loaded sorted numbers: {sorted_numbers}"")
        else:
            print(""Failed to load the file."")
    else:
        print(""Invalid choice. Please try again."")

if __name__ == ""__main__"":
    main_menu()

