import hashlib
import logging
import os
from threading import Thread
from queue import Queue
from collections import deque

class CryptographicKeyGenerator:
    def __init__(self):
        self.keys = deque()
        self.logger = logging.getLogger('CryptographicKeyGenerator')
        self.logger.setLevel(logging.INFO)

    @staticmethod
    def generate_key():
        key = hashlib.sha256(os.urandom(32)).hexdigest()
        return key

    def generate_keys(self, num_keys, output_dir):
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        queue = Queue()
        threads = []

        for _ in range(num_keys):
            thread = Thread(target=self.generate_key_loop, args=(queue,))
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()

        self.write_keys_to_file(queue, output_dir)

    def generate_key_loop(self, queue):
        while True:
            key = self.generate_key()
            if not self.is_valid_hex(key):
                continue
            queue.put(key)

    @staticmethod
    def is_valid_hex(s):
        return set(s).issubset(set('0123456789ABCDEFabcdef'))

    def write_keys_to_file(self, queue, output_dir):
        index = 0
        while not queue.empty():
            key = queue.get()
            self.logger.info(f""Generated Key {index}: {key}"")
            with open(os.path.join(output_dir, f""key_{index}.txt""), 'w') as file:
                file.write(key)
            index += 1

    def add_key(self, key):
        if not self.is_valid_hex(key):
            raise ValueError(""Invalid key"")
        self.keys.append(key)

    def remove_key(self, key):
        if key in self.keys:
            self.keys.remove(key)
        else:
            raise ValueError(""Key not found"")

    def list_keys(self):
        return list(self.keys)

    def __del__(self):
        del self.keys
