        with open(filename, 'r') as f:
            lines = sorted(f.readlines())
            last_line = lines[-1].strip()
            sequence_number = int(last_line.split(' ')[-1])

        modified_filename = f""{os.path.splitext(filename)[0]}_{sequence_number}{file_type}""
        return modified_filename

    except ValueError:
        return ""Error: Last line does not contain a valid sequence number.""
    except Exception as e:
        return f""An error occurred: {str(e)}""

def batch_process_files(filenames: List[str], output_type: str) -> None:
    for filename in filenames:
        result = process_file(filename, output_type)
        print(result)

if __name__ == ""__main__"":
    if len(sys.argv) < 3:
        print(""Usage: python script.py <filenames> <output_type>"")
    else:
        filenames = sys.argv[1:]
        output_type = sys.argv[2]
        batch_process_files(filenames, output_type)
