def generate_key_and_iv(block_size):
    return get_random_bytes(block_size), get_random_bytes(block_size)

def encrypt_text(text, encryption_algorithm):
    if encryption_algorithm == ""AES"":
        block_size = 16
        key, iv = generate_key_and_iv(block_size)
        cipher = AES.new(key, AES.MODE_CBC)
        encrypted_text = cipher.encrypt(pad(text.encode(), block_size))
        return ""-"".join([key.hex(), iv.hex(), encrypted_text.hex()])
    elif encryption_algorithm == ""DES3"":
        block_size = 8
        key, iv = generate_key_and_iv(block_size)
        cipher = DES3.new(key, DES3.MODE_CBC)
        encrypted_text = cipher.encrypt(pad(text.encode(), block_size))
        return ""-"".join([key.hex(), iv.hex(), encrypted_text.hex()])
    elif encryption_algorithm == ""ARC4"":
        block_size = 16
        key = get_random_bytes(16)
        cipher = ARC4.new(key)
