import random
import csv

class GenerateRandomNumbers:
    def __init__(self):
        self.min_value = None
        self.max_value = None
        self.array_size = None

    def set_range(self, min_value, max_value):
        self.min_value = min_value
        self.max_value = max_value

    def set_array_size(self, array_size):
        self.array_size = array_size

    def generate_numbers(self):
        if not (isinstance(self.min_value, int) and isinstance(self.max_value, int)):
            raise ValueError(""Min and Max values must be integers"")

        if self.min_value > self.max_value:
            raise ValueError(""Invalid range. Min value must not exceed Max value"")

        numbers = []
        for _ in range(self.array_size):
            num = random.randint(self.min_value, self.max_value)
            if random.random() < 0.5:
                num *= -1
            elif random.uniform(0, 1) > 0.8:
                num += float(random.randint(-100, 100)) / 100.0
            numbers.append(num)

        return numbers

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

def mergesort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left_half = arr[:mid]
    right_half = arr[mid:]
    return merge(mergesort(left_half), mergesort(right_half))

def merge(left, right):
    merged = []
    left_index = 0
    right_index = 0
    while left_index < len(left) and right_index < len(right):
        if left[left_index] <= right[right_index]:
            merged.append(left[left_index])
            left_index += 1
        else:
            merged.append(right[right_index])
            right_index += 1
    merged.extend(left[left_index:])
    merged.extend(right[right_index:])
    return merged

def save_to_csv(filename, data):
    with open(filename, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        for row in data:
            writer.writerow(row)

if __name__ == ""__main__"":
    # Initialize the GenerateRandomNumbers module
    random_generator = GenerateRandomNumbers()

    try:
        min_value = int(input(""Enter minimum value: ""))
        max_value = int(input(""Enter maximum value: ""))
        array_size = int(input(""Enter array size: ""))

        random_generator.set_range(min_value, max_value)
        random_generator.set_array_size(array_size)

        numbers = random_generator.generate_numbers()
        print(""Generated Numbers:"", numbers)

        algorithm_choice = input(""Choose sorting algorithm (1 - Bubble Sort, 2 - Quicksort, 3 - Mergesort): "")
        if algorithm_choice == ""1"":
            sorted_numbers = bubble_sort(numbers)
        elif algorithm_choice == ""2"":
            sorted_numbers = quicksort(numbers)
        elif algorithm_choice == ""3"":
            sorted_numbers = mergesort(numbers)

        print(""Sorted Numbers:"", sorted_numbers)

        save_to_csv(""output.csv"", [sorted_numbers])

    except ValueError as e:
        print(""Error: "", str(e))
