from flask import Flask, request, jsonify
import json
from pymongo import MongoClient

app = Flask(__name__)

# Connect to MongoDB
client = MongoClient('mongodb://localhost:27017/')
db = client['mydatabase']
collection = db['mycollection']

@app.route('/api/data', methods=['POST'])
def process_data():
    try:
        # Get JSON data from request body
        data = json.loads(request.get_json())

        # Perform CRUD operations on MongoDB database
        if 'create' in data:
            collection.insert_one(data['create'])
        elif 'read' in data:
            result = list(collection.find({**data['read']}, {'_id': False}))
            return jsonify(result)
        elif 'update' in data:
            update_data = {k: v for k, v in data['update'].items() if k != '_id'}
            collection.update_one({'_id': data['update']['_id']}, {'$set': update_data})
        elif 'delete' in data:
            collection.delete_one({'_id': data['delete']})

        # Log successful API call
        with open('api_log.txt', 'a') as f:
            f.write(f""API call successful at {request.timestamp}\n"")

        return jsonify({'message': 'Data processed successfully'})
    except Exception as e:
        app.logger.error(f'Error processing data: {str(e)}')
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
