def analyzeWebPageVisits(visit_records, threshold):
    recent_visit_threshold = datetime.datetime.now() - datetime.timedelta(days=30)

    country_visits = {}
    for visit in visit_records:
        if visit[""country""] not in country_visits:
            country_visits[visit[""country""]] = {}
        if visit[""visitTime""] > recent_visit_threshold and visit[""country""] == ""USA"":
            page_visit_count = country_visits[visit[""country""]].get(visit[""visitedPage""], 0)
            country_visits[visit[""country""]][visit[""visitedPage""]] = page_visit_count + 1

    top_pages_by_country = {}
    for country, pages in country_visits.items():
        top_pages = sorted(pages.items(), key=lambda x: x[1], reverse=True)[:threshold]
        top_pages_by_country[country] = {page: count for page, count in top_pages}

    return top_pages_by_country
