import requests
import logging
from functools import wraps

class API:
    def __init__(self, api_key):
        self.api_key = api_key
        self.requests_session = requests.Session()
        self.requests_session.headers.update({'Authorization': f'Bearer {api_key}'})

def log_info(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        logging.info(f'{func.__name__} called with args: {args}, kwargs: {kwargs}')
        return func(*args, **kwargs)
    return wrapper

def cache_response(func):
    cache = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key in cache:
            return cache[key]

        result = func(*args, **kwargs)
        cache[key] = result
        return result

    return wrapper

def api_call(api_endpoint, params={}):
    try:
        response = requests.get(api_endpoint, params=params, timeout=5)
    except (requests.exceptions.ConnectionError, requests.exceptions.Timeout):
        logging.warning(f'Failed to connect to API: {api_endpoint}')
        return None
    except Exception as e:
        logging.error(f'API request failed: {e}')
        return None

    if response.status_code == 401:
        logging.info('Authentication failed. Check your API key.')
        return None

    try:
        data = response.json()
    except ValueError:
        logging.error(f'Response was not in JSON format: {response.text}')
        return None

    return {'data': data, 'status_code': response.status_code}

def main(api_endpoint, input_list):
    if not isinstance(input_list, list) or any(not isinstance(x, int) for x in input_list):
        logging.error('Invalid input. Please provide a list of integers.')
        return None

    output_dict = {}

    @log_info
    @cache_response
    def call_api(params={}):
        return api_call(api_endpoint, params)

    for param in input_list:
        output_dict[param] = call_api({'param': param})

    return output_dict

