from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import hashlib
import json
from flask_httpauth import HTTPBasicAuth

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///test.db'
app.config['SECRET_KEY'] = 'supersecretkey'

db = SQLAlchemy(app)
basic_auth = HTTPBasicAuth()

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

@app.route('/register', methods=['POST'])
@basic_auth.login_required
def register():
    new_user = User(username=request.json['username'], password=hashlib.sha256(request.json['password'].encode()).hexdigest())
    db.session.add(new_user)
    db.session.commit()
    return jsonify({'message': 'User created successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    username = request.json['username']
    password = hashlib.sha256(request.json['password'].encode()).hexdigest()
    user = User.query.filter_by(username=username).first()
    if user and user.password == password:
        return jsonify({'token': 'secure_token'}), 200
    else:
        return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/api/endpoint', methods=['POST'])
@basic_auth.login_required
def api_endpoint():
    # Process the request data here
    return jsonify({'response': 'Data processed successfully'}), 201

if __name__ == '__main__':
    app.run(debug=True)
