import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import os
import hashlib
from functools import lru_cache

@lru_cache(maxsize=None)
def generate_key():
    return ''.join([hex(int(str(random.getrandbits(16))[2:], 2))[2:].zfill(8) for _ in range(4)])

class KeyGenerator:
    def __init__(self, num_keys, output_dir):
        self.num_keys = num_keys
        self.output_dir = output_dir
        self.logger = logging.getLogger(__name__)
        self.keys = []
        self.lock = threading.Lock()

    def generate(self):
        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = {executor.submit(generate_key): i for i in range(self.num_keys)}
            for future in as_completed(futures):
                key = future.result()
                if len(key) != 32 or not all(c in '0123456789abcdef' for c in key):
                    self.logger.error(""Invalid key: {}"".format(key))
                    return False
                with self.lock:
                    self.keys.append(key)
            if len(self.keys) == self.num_keys:
                return True

    def get_keys(self):
        return self.keys

    def save_keys(self, filename='keys.txt'):
        with open(os.path.join(self.output_dir, filename), 'w') as f:
            f.write('\n'.join(self.keys))

    def load_keys(self, filename):
        try:
            with open(filename, 'r') as f:
                self.keys = [line.strip() for line in f.readlines()]
        except FileNotFoundError:
            pass

    def __del__(self):
        if hasattr(self, 'keys'):
            del self.keys
