from typing import List

class SessionHandler:
    def __init__(self, session_token_length: int):
        self.session_token_length = session_token_length
        self.session_token_chars = string.ascii_letters + string.digits

    def generate_session_token(self) -> str:
        return ''.join(random.choice(self.session_token_chars) for _ in range(self.session_token_length))

    def hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def process_file(self, file_path: str) -> None:
        try:
            with open(file_path, 'rb') as file:
                chunk_size = 1024 * 1024
                chunks = [file.read(chunk_size) for _ in range(int((file.seek(0, 2) / chunk_size)) + 1)]
                hashes = []
                largest_numbers = []
                total_hash = hashlib.md5()

                for i, chunk in enumerate(chunks):
                    try:
                        data_ints: List[int] = [int.from_bytes(chunk, 'big') for chunk in chunk.split(b'\x00')]
                        max_num = max(data_ints)
                        largest_numbers.append(max_num)
                        hashes.append(hashlib.md5(chunk).hexdigest())
                        total_hash.update(chunk)
                    except Exception as e:
                        print(f""Error processing chunk {i}: {e}"")

                with open('session_log.txt', 'w') as log_file:
                    for i in range(len(hashes)):
                        log_file.write(f""Largest number: {largest_numbers[i]}, Hash: {hashes[i]}\n"")
        except FileNotFoundError:
            print(""File not found."")
        except Exception as e:
            print(f""An error occurred: {e}"")
