from typing import Dict
import re

def read_config_file(filename: str) -> Dict[str, any]:
    config = {}
    pattern = re.compile(r'^(?P<key>[^=]+)=(?P<value>.+)$')

    try:
        with open(filename, 'r') as file:
            for line in file:
                match = pattern.match(line)
                if match:
                    key = match.group('key').strip()
                    value = match.group('value').strip()

                    if '=' not in value:  # check for correct format
                        config[key] = int(value) if value.isdigit() else float(value) if value.replace('.','',1).isdigit() else value
                    else:
                        print(f""Invalid key-value pair: {line.strip()}"")

    except FileNotFoundError:
        print(f""File not found: {filename}"")
    except Exception as e:
        print(f""An error occurred: {e}"")

    return config

