def collatz_dp(n):
    cache = {1: 0}
    def helper(x):
        if x not in cache:
            if x % 2 == 0:
                cache[x] = 1 + helper(x // 2)
            else:
                cache[x] = 1 + helper(3 * x + 1)
        return cache[x]
    return helper(n)

def collatz_mathematical(n):
    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return len(sequence) - 1

def main():
    print(""Choose a method: "")
    print(""1. Dynamic Programming"")
    print(""2. Mathematical Optimization"")
    choice = int(input(""Enter your choice (1 or 2): ""))

    if choice == 1:
        n = int(input(""Enter the value of n: ""))
        try:
            result = collatz_dp(n)
            print(f""The {n}th value in the Collatz sequence is {result}."")
        except Exception as e:
            print(f""Error: {str(e)}"")

    elif choice == 2:
        n = int(input(""Enter the value of n: ""))
        try:
            result = collatz_mathematical(n)
            print(f""The {n}th value in the Collatz sequence is {result}."")
        except Exception as e:
            print(f""Error: {str(e)}"")

    else:
        print(""Invalid choice. Please choose 1 or 2."")

if __name__ == ""__main__"":
    main()

def test_collatz_dp():
    assert collatz_dp(1) == 0
    assert collatz_dp(16) == 4
    assert collatz_dp(-10) == ""Error: Input must be a non-negative integer.""

def test_collatz_mathematical():
    assert collatz_mathematical(1) == 0
    assert collatz_mathematical(16) == 4
    assert collatz_mathematical(-10) == ""Error: Input must be a non-negative integer.""
