func NewHashTable(size int) *HashTable {
    h := &HashTable{size: size, buckets: make([]*node, size)}
    for i := range h.buckets {
        h.buckets[i] = nil
    }
    return h
}

func (h *HashTable) Put(key string, value interface{}) error {
    index := hash(key) % len(h.buckets)
