class DynamicQueue:
    def __init__(self):
        self.items = [None] * 2
        self.front = self.rear = -1

    def enqueue(self, item):
        if (self.rear) % len(self.items) == len(self.items) - 1:
            self._resize(2 * len(self.items))
        self.items[(self.rear + 1) % len(self.items)] = item
        self.rear = (self.rear + 1) % len(self.items)

    def dequeue(self):
        if self.is_empty():
            return None
        item = self.items[self.front + 1]
        self.items[self.front + 1] = None
        if self.front == self.rear:
            self._resize(len(self.items) // 2)
        else:
            self.front = (self.front + 1) % len(self.items)
        return item

    def peek(self):
        if self.is_empty():
            return None
        return self.items[self.front + 1]

    def is_empty(self):
        return self.front == self.rear and self.items[self.front + 1] is None

    def size(self):
        if self.is_empty():
            return 0
        return (self.rear - self.front + 1) % len(self.items)

    def _resize(self, new_capacity):
        new_items = [None] * new_capacity
        for i in range(self.size()):
            new_items[i] = self.items[(self.front + 1 + i) % len(self.items)]
        self.items = new_items
        self.front = 0
        self.rear = self.size() - 1

    def from_list(self, lst):
        self.items = [None] * len(lst)
        self.front = self.rear = -1
        for item in lst:
            self.enqueue(item)

# Test cases
