import os
import requests

class FileUploader:
    def __init__(self, api_uploader_service):
        self.api_uploader_service = api_uploader_service

    def upload_file(self, file_path, name, endpoint):
        try:
            if not os.path.exists(file_path):
                raise FileNotFoundError(f""The file {file_path} does not exist"")

            with open(file_path, 'rb') as f:
                files = {'file': f}
                params = {'name': name}

                response = self.api_uploader_service.upload(endpoint, files=files, params=params)

                if response.status_code == 200:
                    print(f""File {name} uploaded successfully to {endpoint}"")
                else:
                    raise Exception(f""Upload failed with status code {response.status_code}"")

        except requests.exceptions.RequestException as e:
            print(f""Error uploading file: {e}"")
        except FileNotFoundError as e:
            print(f""Error: {e}"")
