import random
import subprocess
import os
import time
from datetime import datetime

class RandomNumberGenerator:
    def __init__(self, min_value, max_value, array_size):
        self.min_value = min_value
        self.max_value = max_value
        self.array_size = array_size

    def generate_random_array(self):
        return [random.randint(self.min_value, self.max_value) for _ in range(self.array_size)]

class SortingAlgorithm:
    def __init__(self, algorithm_name):
        self.algorithm_name = algorithm_name

    def bubble_sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n-i-1):
                if array[j] > array[j+1]:
                    array[j], array[j+1] = array[j+1], array[j]
        return array

    def quicksort(self, array):
        if len(array) <= 1:
            return array
        pivot = array[len(array)//2]
        left = [x for x in array if x < pivot]
        middle = [x for x in array if x == pivot]
        right = [x for x in array if x > pivot]
        return self.quicksort(left) + middle + self.quicksort(right)

    def mergesort(self, array):
        if len(array) <= 1:
            return array
        mid = len(array)//2
        left_half = self.mergesort(array[:mid])
        right_half = self.mergesort(array[mid:])
        return self.merge(left_half, right_half)

    def merge(self, left, right):
        result = []
        while len(left) > 0 and len(right) > 0:
            if left[0] <= right[0]:
                result.append(left.pop(0))
            else:
                result.append(right.pop(0))
        return result + left + right

class ServiceManager:
    def __init__(self):
        pass

    def start_service(self, service_name):
        try:
            subprocess.run(['service', service_name, 'start'])
        except Exception as e:
            print(f""Error starting {service_name}: {str(e)}"")

    def stop_service(self, service_name):
        try:
            subprocess.run(['service', service_name, 'stop'])
        except Exception as e:
            print(f""Error stopping {service_name}: {str(e)}"")

def main():
    min_value = int(input(""Enter the minimum value: ""))
    max_value = int(input(""Enter the maximum value: ""))
    array_size = int(input(""Enter the array size: ""))
    algorithm_name = input(""Enter the sorting algorithm name (bubble, quick, merge): "")

    rng = RandomNumberGenerator(min_value, max_value, array_size)
    array = rng.generate_random_array()

    if algorithm_name.lower() == 'bubble':
        algo = SortingAlgorithm('Bubble Sort')
        sorted_array = algo.bubble_sort(array)
    elif algorithm_name.lower() == 'quick':
        algo = SortingAlgorithm('Quick Sort')
        sorted_array = algo.quicksort(array)
    elif algorithm_name.lower() == 'merge':
        algo = SortingAlgorithm('Merge Sort')
        sorted_array = algo.mergesort(array)
    else:
        print(""Invalid sorting algorithm. Using Bubble Sort as default."")
        algo = SortingAlgorithm('Bubble Sort')
        sorted_array = algo.bubble_sort(array)

    start_time = time.time()
    for _ in range(10):
        print(sorted_array)
        time.sleep(1)
    end_time = time.time()

    print(f""Sorting took {end_time - start_time} seconds."")

if __name__ == ""__main__"":
    main()
