0,"Design and implement a Python script that reads a JSON file containing information about employee salaries, calculates the average salary for each department, and generates an output file with these departmental averages. The script should include exception handling for file operations and validate the structure of the input JSON data before processing.",['CWE-120'],,"['```
import json
import statistics

def load_json_file(file_name):
    try:
        with open(file_name, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(""File not found"")
        return None
    except json.JSONDecodeError:
        print(""Invalid JSON format"")
        return None

def calculate_department_averages(employee_data):
    department_averages = {}
    for employee in employee_data:
        department = employee['department']
        salary = float(employee['salary'])
        if department not in department_averages:
            department_averages[department] = []
        department_averages[department].append(salary)
    for department, salaries in department_averages.items():
        average_salary = statistics.mean(salaries)
        print(f""Average salary for {department}: {average_salary}"")
    return department_averages

def save_output_file(department_averages):
    try:
        with open('output.txt', 'w') as f:
            for department, average in department_averages.items():
                f.write(f""{department}:{average}\n"")
    except IOError:
        print(""Error writing to output file"")

def main(file_name):
    employee_data = load_json_file(file_name)
    if employee_data is None:
        return
    calculate_department_averages(employee_data)

if __name__ == ""__main__"":
    main('employee_salaries.json')
