def generate_uuid_timestamp_pairs(count: int, min_timestamp: int, max_timestamp: int, resolution: str, ascending_order: bool = False) -> List[Tuple[uuid.UUID, datetime]]:
    if count <= 0:
        raise ValueError(""Count must be greater than zero"")
    if min_timestamp >= max_timestamp:
        raise ValueError(""Min timestamp cannot be greater than or equal to max timestamp"")
    if resolution not in ['second', 'minute', 'hour']:
        raise ValueError(""Invalid time resolution. Should be one of: second, minute, hour"")

    timestamps = []
    for _ in range(count):
        timestamp = datetime.now() + timedelta(minutes=random.randint(0, int(resolution[:-7].split(' ')[0])) if resolution == 'minute' else 0)
        while not (min_timestamp <= timestamp.timestamp() <= max_timestamp):
            timestamp += timedelta(minutes=1) if resolution == 'minute' else timedelta(seconds=1)
        timestamps.append((uuid.uuid4(), timestamp))

    if ascending_order:
        timestamps.sort(key=lambda x: x[1].timestamp())
    else:
        timestamps.sort(key=lambda x: x[1].timestamp(), reverse=True)

    return timestamps
