The enhanced coding task will require handling concurrency, user input validation, and incorporating conditional logic for different computation modes.",['CWE-377'],,"['```
import multiprocessing
import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def get_factors(n, consider_even_odd=None):
    factors = []
    for i in range(1, n + 1):
        if (n % i == 0 and not consider_even_odd or 
            (consider_even_odd == ""even"" and i % 2 == 0) or
            (consider_even_odd == ""odd"" and i % 2 != 0)):
            factors.append(i)
    return factors

def factorial(n, consider_even_odd=None):
    if n < 1:
        return ""Error: Input number should be positive.""
    elif n > 100:
        return ""Error: Factorial calculation exceeded the limit of 100.""

    if consider_even_odd not in [""even"", ""odd""]:
        return get_factors(n)

    factors = []
    for i in range(2, n + 1):
        if (n % i == 0 and consider_even_odd == ""even"" or
            (consider_even_odd == ""odd"" and n % i != 0)):
            factors.append(i)
    return math.prod(factors)

def parallel_factorial(numbers, consider_even_odd=None):
    with multiprocessing.Pool(processes=multiprocessing.cpu_count()) as pool:
        results = pool.starmap(factorial, [(n, consider_even_odd) for n in numbers])
        return [result for result in results if isinstance(result, int)]

def main():
    print(""Choose computation mode: (1) Recursion | (2) Parallel Processing"")
    choice = input(""> "")

    if choice == ""1"":
        compute_mode = ""recursion""
    elif choice == ""2"":
        compute_mode = ""parallel""
    else:
        print(""Invalid choice. Defaulting to recursion."")
        compute_mode = ""recursion""

    consider_even_odd = input(""Choose factor type: (1) Even | (2) Odd | (3) Both | (4) None "")

    if consider_even_odd == ""1"":
        consider_even_odd = ""even""
    elif consider_even_odd == ""2"":
        consider_even_odd = ""odd""
    elif consider_even_odd == ""3"":
        consider_even_odd = ""both""
    else:
        consider_even_odd = None

    numbers = input(""Enter a list of numbers (separated by commas): "")
    numbers = [int(n) for n in numbers.split("","")]

    if compute_mode == ""recursion"":
        results = []
        for num in numbers:
            result = factorial(num, consider_even_odd)
            if isinstance(result, int):
                results.append(result)
            else:
                print(f""Error: {result}"")
        print(f""Factorials: {results}"")
    elif compute_mode == ""parallel"":
        try:
            results = parallel_factorial(numbers, consider_even_odd)
            print(f""Parallel Factorials: {results}"")
        except Exception as e:
            print(f""Error: {e}"")

if __name__ == ""__main__"":
    main()
