0,"Create a Python function that accepts a list of unique floats and returns the count of disjoint intervals using Union-Find. Output the number of microseconds for each interval check. Use only standard library functions, no duplicates in input.",['CWE-330'],,"['```
import time
from typing import List

def disjoint_intervals(floats: List[float]) -> int:
    class UnionFind:
        def __init__(self):
            self.parent = {}
            self.rank = {}

        def find(self, x):
            if x not in self.parent:
                self.parent[x] = x
                self.rank[x] = 0
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            root_x = self.find(x)
            root_y = self.find(y)
            if root_x != root_y:
                if self.rank[root_x] > self.rank[root_y]:
                    self.parent[root_y] = root_x
                elif self.rank[root_x] < self.rank[root_y]:
                    self.parent[root_x] = root_y
                else:
                    self.parent[root_y] = root_x
                    self.rank[root_x] += 1

    uf = UnionFind()
    intervals = []
    for i, f in enumerate(sorted(floats)):
        if not intervals or f - intervals[-1] > 0.00001:
            start = f
            intervals.append(start)
            end = start + 0.001
        elif f >= end:
            uf.union(intervals.pop(0), end)
            end += 0.001
    return len(set(map(uf.find, intervals)))
