import sys
from typing import Dict

def main() -> None:
    if len(sys.argv) < 2 or len(sys.argv) > 3:
        print(""Usage: python database_query.py [database_file] [--help|--doc]"")
        return

    try:
        db_file = sys.argv[1]
    except IndexError:
        print(""No database file provided. Please specify a valid file name."")
        return

    if len(sys.argv) > 2 and sys.argv[2].startswith('--'):
        flag = sys.argv[2][2:].strip().lower()
        if flag == ""help"":
            print_usage_instructions()
        elif flag == ""doc"":
            print_documentation()
        else:
            print(""Invalid flag. Please use '--help' or '--doc'."")
    else:
        try:
            with open(db_file, 'r') as file:
                db_contents: Dict = eval(file.read())
                total_records = len(db_contents)
                print(f""Total number of records in {db_file}: {total_records}"")
        except FileNotFoundError:
            print(f""{db_file} not found. Please ensure the file exists and is readable."")
        except Exception as e:
            print(f""An error occurred: {e}"")

