def validateAPIResponse(json_string, *optional_fields):
    try:
        response = json.loads(json_string)
        if not isinstance(response, dict):
            return False
        required_fields = [""status"", ""code"", ""message""]
        for field in required_fields:
            if field not in response or (field == ""status"" and response[field] not in [""success"", ""error""]) or \
               (field == ""code"" and not isinstance(response[field], int) or response[field] <= 0) or \
               (field == ""message"" and not isinstance(response[field], str) or len(response[field]) == 0):
                return False
        if optional_fields:
            for field in optional_fields:
                if field in response and not validateField(response, field):
                    return False
        return True
    except Exception as e:
        print(f""Error: {e}"")
        return False

def validateField(json_object, field):
    try:
        value = json_object[field]
        if isinstance(value, dict):
            for key in value:
                if not validateAPIResponse(json.dumps({key: value[key]}), *optional_fields):
                    return False
        elif not (isinstance(value, str) or isinstance(value, int)):
            return False
        return True
    except Exception as e:
        print(f""Error: {e}"")
        return False
