def hash_file(filename, command):
    if command == 'md5':
        hasher = hashlib.md5()
    elif command == 'sha1':
        hasher = hashlib.sha1()
    elif command == 'sha256':
        hasher = hashlib.sha256()

    with open(filename, 'rb') as file:
        chunk = file.read(4096)
        while chunk:
            hasher.update(chunk)
            chunk = file.read(4096)

    return hasher.hexdigest()""]",86,[1],"['CWE-328', 'CWE-327']",True,0,0,0,

