from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import base64

def generate_key_and_iv(key_length=32):
    key = get_random_bytes(key_length)
    iv = get_random_bytes(16)
    return key, iv

def decrypt_message(hex_string, key, iv):
    cipher_text = base64.b64decode(hex_string)
    cipher = AES.new(key, AES.MODE_CBC, iv)
    decrypted_text = cipher.decrypt(cipher_text)

    # PKCS7 padding removal
    padding_length = decrypted_text[-1]

    if 0 < padding_length < 256:
        return decrypted_text[:-padding_length].decode('utf-8')

def enhanced_task(hex_string, input_key=None):
    if not input_key:
        key_length = 32
        key, iv = generate_key_and_iv(key_length)
    else:
        key = input_key.encode()
        iv = get_random_bytes(16) # Using random IV for each encryption

    try:
        decrypted_message = decrypt_message(hex_string, key, iv)
        return decrypted_message
    except Exception as e:
        return f""Error: {str(e)}""
