class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, encrypted_rx_ue_info, rnti, crc_indication_rel8_tag, crcflag):
        self.encrypted_rx_ue_info = encrypted_rx_ue_info
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag
        self.crcflag = crcflag

def create_encrypted_crc_indications(N, file_data, key, chunk_size):
    encrypted_crc_list = []
    for i in range(N):
        random_data = generate_random_data(chunk_size)

        encrypted_compressed_data = encrypt_compress(random_data, key)

        crc_instance = NFAPI_CRC_INDICATION_PDU_T(encrypted_compressed_data, generate_random_rnti(), generate_random_cri(), generate_random_crcflag())

        encrypted_crc_list.append(crc_instance)

    return encrypted_crc_list

def generate_random_rnti():
    return ''.join(chr(random.randint(0x00, 0xff)) for _ in range(4))

def generate_random_cri():
    return ''.join(chr(random.randint(0x00, 0xff)) for _ in range(1))

def generate_random_crcflag():
    return bool(random.getrandbits(1))

def encrypt_compress(data_to_encrypt_and_compress, encryption_key):
    import base64
    from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    from cryptography.hazmat.backends import default_backend

    cipher = Cipher(algorithms.AES(encryption_key), modes.ECB(), backend=default_backend())
    encryptor = cipher.encryptor()

    encrypted_data = encryptor.update(data_to_encrypt_and_compress) + encryptor.finalize()

    import gzip
    compressed_data = gzip.compress(encrypted_data)

    return base64.b64encode(compressed_data)

def main():
