import queue
import ctypes

def python_queue_management(queue_list):
    queue_obj = queue.PriorityQueue()
    for num in queue_list:
        if not queue_obj.qsize():
            queue_obj.put(num)
        else:
            temp = queue_obj.get()
            while queue_obj.qsize() and temp <= queue_obj.queue[0]:
                queue_obj.put(temp)
                temp = queue_obj.get()
            queue_obj.put(num)

    return list(queue_obj.queue)

def find_smallest_integer(smallest_queue):
    smallest_num = queue.PriorityQueue()
    for num in smallest_queue:
        if not smallest_num.qsize():
            smallest_num.put(num)
        else:
            temp = smallest_num.get()
            while smallest_num.qsize() and temp <= smallest_num.queue[0]:
                smallest_num.put(temp)
                temp = smallest_num.get()
            smallest_num.put(num)

    return list(smallest_num.queue)

