    result = []
    for i, code in enumerate(color_codes):
        rgb = tuple(int(code.lstrip('#')[i:i+2], 16) for i in (0, 4, 8))
        if i % 2 == 0:
            transformed_rgb = tuple(min(255, x + 50) for x in rgb)
        else:
