import ApiDBConnector
class DatabaseManager:
    def __init__(self, db_name: str, table_name: str, endpoint: str):
        self.db_name = db_name
        self.table_name = table_name
        self.endpoint = endpoint
        self.connector = ApiDBConnector(self.endpoint)

    def query_data(self, query_params: dict):
        try:
            response = self.connector.query(self.db_name, self.table_name, query_params)
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f""Error querying data. Status code: {response.status_code}"")
        except Exception as e:
            print(f""An error occurred: {str(e)}"")
            return None

    def update_data(self, updates: dict):
        try:
            self.connector.update(self.db_name, self.table_name, updates)
            return ""Data updated successfully""
        except Exception as e:
            print(f""An error occurred while updating data: {str(e)}"")
            return None

    def delete_data(self, filter_params: dict):
        try:
            response = self.connector.delete(self.db_name, self.table_name, filter_params)
            if response.status_code == 200:
                return ""Data deleted successfully""
            else:
                raise Exception(f""Error deleting data. Status code: {response.status_code}"")
        except Exception as e:
            print(f""An error occurred while deleting data: {str(e)}"")
            return None

    def get_data(self, filter_params: dict):
        try:
            response = self.connector.get(self.db_name, self.table_name, filter_params)
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f""Error retrieving data. Status code: {response.status_code}"")
        except Exception as e:
            print(f""An error occurred while retrieving data: {str(e)}"")
            return None
