import hashlib
import subprocess

def generate_access_token(command, filename, hash_algorithm):
    if not isinstance(command, str) or not isinstance(filename, str) or not isinstance(hash_algorithm, str):
        return {""status"": ""error"", ""message"": ""Invalid parameter types""}, None

    try:
        output = subprocess.check_output(command.split("" ""))
    except Exception as e:
        return {""status"": ""error"", ""message"": str(e)}, None

    if hash_algorithm == 'sha256':
        hasher = hashlib.sha256()
    elif hash_algorithm == 'md5':
        hasher = hashlib.md5()
    elif hash_algorithm == 'blake2b':
        hasher = hashlib.blake2b()
    else:
        return {""status"": ""error"", ""message"": ""Unsupported hashing algorithm""}, None

    with open(filename, 'rb') as file:
        chunk = file.read(4096)
        while chunk:
            hasher.update(chunk)
            chunk = file.read(4096)

    access_token = hasher.hexdigest()
    return {""status"": ""success"", ""token"": access_token}, output.decode('utf-8')
