def validate_input_json(input_json):
    required_fields = ['device_id', 'mac_address', 'signal_strength']
    if not all(field in input_json for field in required_fields):
        raise ValueError(""Input JSON is missing required fields"")

def encrypt_signal_strength(signal_strength, key, cipher_mode='decrypt'):
    if cipher_mode == 'encrypt':
        return AES.encrypt(str(signal_strength).encode(), key.encode())
    elif cipher_mode == 'decrypt':
        try:
            decrypted = AES.decrypt(AES.encrypt(str(signal_strength).encode(), key.encode()))
            return int(decrypted.decode())
        except ValueError:
            raise ValueError(""Invalid decryption"")

def create_BLE_scan_responses(input_json, keys):
    BLE_responses = []
    for response in input_json['responses']:
        device_id = response['device_id']
        mac_address = ''.join(random.choices('0123456789abcdef', k=12))
        signal_strength = encrypt_signal_strength(response['signal_strength'], random.choice(keys))
        BLE_response = {'device_id': device_id, 'mac_address': mac_address, 
                        'signal_strength': signal_strength}
        BLE_responses.append(BLE_response)
    return BLE_responses

