class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    def __repr__(self):
        return f""TreeNode({self.val})""

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

    def __repr__(self):
        return f""ListNode({self.val}, {next(self)})""

def build_linked_list(root, current_depth=0):
    if root is None or current_depth > depth_limit:
        return None

    if root.val == target_value:
        head = ListNode(root.val)
    else:
        head_left = build_linked_list(root.left, current_depth + 1)
        head_right = build_linked_list(root.right, current_depth + 1)

        if (head_left is not None and current_depth <= depth_limit < max_nodes and head_left.next is None) or (head_right is not None and current_depth <= depth_limit < max_nodes and head_right.next is None):
            if root.val > target_value:
                if head_left is not None:
                    head.next = head_left
                else:
                    head.next = ListNode(root.val)
            elif head_right is not None:
                head.next = head_right

    return head

def create_linked_list_from_binary_tree(root, target_value, depth_limit, max_nodes, memory_limit):
    linked_list_head = build_linked_list(root)

    total_nodes_in_memory = 0
    current_node = linked_list_head
    while current_node is not None:
        total_nodes_in_memory += 1
        current_node = current_node.next

    if total_nodes_in_memory > memory_limit:
        return None

    return linked_list_head


