import hashlib
import os
import string

class FileSessionHandler:
    def __init__(self):
        self.session_tokens = []
        self.password_hashes = {}
        self.log_file_path = 'session_log.txt'

    def generate_session_token(self, length=10):
        import secrets
        token = ''.join(secrets.choice(string.ascii_letters + string.digits) for _ in range(length))
        return token

    def hash_password(self, password):
        import hashlib
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        return hashed_password

    def process_file(self, input_file_path):
        try:
            with open(input_file_path, 'rb') as file:
                chunk_size = 1024 * 1024  # 1 MB chunks
                while True:
                    chunk = file.read(chunk_size)
                    if not chunk:
                        break
                    integers = [int(x) for x in chunk.decode().split()]
                    largest_integer = max(integers)
                    md5_hash = hashlib.md5(str(largest_integer).encode()).hexdigest()
                    with open(self.log_file_path, 'a') as log_file:
                        log_file.write(f""Largest integer: {largest_integer}, MD5 hash: {md5_hash}\n"")
        except FileNotFoundError:
            print(""Error: File not found."")
