import sys
from optparse import OptionParser

def parse_options():
    parser = OptionParser()
    parser.add_option(""-f"", ""--file"", dest=""input_file"")
    parser.add_option(""-o"", ""--output"", action=""store_true"", default=False)
    return parser.parse_args()

def read_file(file_name):
    try:
        with open(file_name, ""r"") as file:
            content = file.read()
            return content.split()
    except FileNotFoundError:
        print(f""Error: File {file_name} not found."")
        sys.exit(1)

def count_words(words):
    return len(words)

def write_result(result, output_file):
    if output_file:
        with open(output_file, ""w"") as file:
            file.write(str(result))
    else:
        print(f""Total number of words: {result}"")

def main():
    options, args = parse_options()
    input_file = options.input_file
    output_file = None

    if not input_file:
        print(""Error: Input file is required."")
        sys.exit(1)

    words = read_file(input_file)
    word_count = count_words(words)
    write_result(word_count, output_file)

if __name__ == ""__main__"":
