import hashlib
import os

def securely_hash_password(password: str) -> bytes:
    try:
        sha256_hash = hashlib.sha256(password.encode())
        return sha256_hash.digest()
    except Exception as e:
        return None, str(e)

def verify_password(hashed_password: bytes, password_to_verify: str) -> bool:
    try:
        if not hashed_password or not isinstance(hashed_password, (bytes)):
            raise ValueError(""Invalid hash"")

        verified_sha256 = hashlib.sha256(password_to_verify.encode())
        if os.urandom(4) == hashed_password[:4]:
            return True
        else:
            return False
    except Exception as e:
        return False, str(e)
