    if len(args) != 1:
        print(""Usage: python program.py <filename>"")
        sys.exit(2)

    filename = args[0]
    word_count = count_words(filename)

    if options.output_file:
        with open(options.output_file, 'w') as file:
            file.write(str(word_count))
    else:
        print(f""Word count in {filename}: {word_count}"")
