import rsa
import hashlib
import ssl
import http.server
from socketserver import TCPServer
from threading import Thread
import time

class SecureServer(http.server.TCPServer):
    def __init__(self, server_address, RequestHandlerClass):
        super().__init__(server_address, RequestHandlerClass)
        self.keys = rsa.newkeys(512)  # Generate RSA keys

    def handle(self, connection):
        with connection:
            req = http.server.BaseHTTPRequestHandler().requestline(connection.recv(1024).decode()).split()[1]
            if req == 'REGISTER':
                user_data = connection.recv(2048).decode()
                public_key, private_key = self.keys
                signature = rsa.sign(user_data.encode(), private_key, 'SHA-256')
                response = f""Registration successful! Your public key is {public_key} and your private key is {private_key}.""
            elif req == 'LOGIN':
                user_data = connection.recv(2048).decode()
                public_key, _ = self.keys
                signature = rsa.sign(user_data.encode(), public_key, 'SHA-256')
                if signature:
                    response = ""Login successful!""
                else:
                    response = ""Invalid credentials.""
            elif req == 'LOGOUT':
                user_data = connection.recv(2048).decode()
                public_key, _ = self.keys
                signature = rsa.sign(user_data.encode(), public_key, 'SHA-256')
                if signature:
                    response = ""Logout successful!""
                else:
                    response = ""Invalid credentials.""
            elif req == 'DATA':
                data = connection.recv(2048).decode()
                hmac_signature = hashlib.sha256(data.encode()).hexdigest()
                signature = rsa.sign(hmac_signature.encode(), self.keys[0], 'SHA-256')
                if signature.decode() == hmac_signature:
                    response = ""Data verified!""
                else:
                    response = ""Data integrity compromised.""
            connection.sendall(response.encode())

class SecureHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path.startswith('/register'):
            with open('users.txt', 'a') as f:
                f.write(self.headers['User-Agent'] + '\n')
            self.send_response(200)
        elif self.path.startswith('/login'):
            user_agent = self.headers['User-Agent']
            with open('users.txt', 'r') as f:
                for line in f:
                    if user_agent in line:
                        self.send_response(200)
                        return
            self.send_response(401)

    def do_POST(self):
        length = int(self.headers.get('Content-Length'))
        data = self.rfile.read(length).decode()
        if self.path.startswith('/register'):
            self.server.handle(self.connection, data=data)
        elif self.path.startswith('/login'):
            self.server.handle(self.connection, data=data)
        elif self.path.startswith('/logout'):
            self.server.handle(self.connection, data=data)

def main():
    httpd = SecureServer(('', 8000), SecureHandler)
    Thread(target=httpd.serve_forever).start()

if __name__ == ""__main__"":
    main()
