class NetworkDeviceState:
    def __init__(self):
        self.device_id = None
        self.operational_status = ""offline""
        self.last_update_time = 0

class SimulatedCommunicationChannel:
    def __init__(self, device_state):
        self.device_state = device_state
        self.message_queue = []

    def send_message(self, message):
        self.message_queue.append(message)
        if self.device_state.operational_status == ""online"":
            print(f""Device {self.device_state.device_id} received message: {message}"")
        else:
            print(f""Device {self.device_state.device_id} is offline and cannot receive messages"")

    def receive_message(self):
        if self.device_state.operational_status == ""offline"":
            return None
        else:
            return self.message_queue.pop(0)

def initialize_network_device_states(num_devices):
    device_states = []
    for _ in range(num_devices):
        new_device_state = NetworkDeviceState()
        new_device_state.device_id = f""device_{len(device_states)}""
        device_states.append(new_device_state)
    return device_states

def simulate_communication(device_states):
    for device_state in device_states:
        communication_channel = SimulatedCommunicationChannel(device_state)
        while True:
            user_input = input(f""Enter a message for device {device_state.device_id} (or 'quit' to exit): "")
            if user_input.lower() == ""quit"":
                break
            communication_channel.send_message(user_input)
            received_message = communication_channel.receive_message()
            if received_message is not None:
                print(f""Device {device_state.device_id} received message: {received_message}"")

# Example usage:
num_devices = 5
device_states = initialize_network_device_states(num_devices)
simulate_communication(device_states)
