import hashlib
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from collections import deque

class DynamicQueueCipher:
    def __init__(self):
        self.queue = deque()
        self.aes_ctx = None
        self.iv = None
        self.password_hash = None

    def from_list(self, lst, password):
        if not self.aes_ctx:
            self.init_cipher_context(password)

        for item in lst:
            encrypted_item = self.encrypt(item)
            self.queue.append(encrypted_item)

    def encrypt(self, item):
        if not self.aes_ctx:
            raise Exception(""Cipher context not initialized"")

        cipher = Cipher(self.aes_ctx, modes.CBC(self.iv), backend=default_backend())
        encryptor = cipher.encryptor()
        padded_item = padding.PKCS7(256).update(item.encode()) + padding.PKCS7(256).block_size * bytes([0])
        encrypted_item = encryptor.update(padded_item) + encryptor.finalize()
        return encrypted_item

    def decrypt(self, item):
        if not self.aes_ctx:
            raise Exception(""Cipher context not initialized"")

        cipher = Cipher(self.aes_ctx, modes.CBC(self.iv), backend=default_backend())
        decryptor = cipher.decryptor()
        decrypted_item = decryptor.update(item) + decryptor.finalize()
        return padding.PKCS7(256).unpad(decrypted_item)

    def dispose_cipher_context(self):
        if self.aes_ctx:
            self.aes_ctx = None
            self.iv = None

    def init_cipher_context(self, password):
        if not self.password_hash:
            self.password_hash = hashlib.sha1(password.encode()).hexdigest()

        self.aes_ctx = Cipher(algorithms.AES(self.password_hash[:32], backend=default_backend()), modes.CBC(self.generate_iv(), backend=default_backend()))
        self.iv = self.generate_iv()

    def generate_iv(self):
        return os.urandom(16)
