class DynamicQueueCipher:
    def __init__(self):
        self.queue = []
        self.cipher_context = None

    def from_list(self, lst):
        for item in lst:
            key = hashlib.sha1(item.encode()).digest()
            iv = os.urandom(16)
            cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
            encryptor = cipher.encryptor()

            encrypted_item = encryptor.update(item.encode()) + encryptor.finalize()
            self.queue.append(encrypted_item)

    def enqueue(self, item):
        if not self.cipher_context:
            key = hashlib.sha1(item.encode()).digest()
            iv = os.urandom(16)
            self.cipher_context = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        else:
            encryptor = self.cipher_context.encryptor()

            encrypted_item = encryptor.update(item.encode()) + encryptor.finalize()
            self.queue.append(encrypted_item)

    def dequeue(self):
