import multiprocessing
from functools import wraps

def parallelize(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        with multiprocessing.Pool(processes=multiprocessing.cpu_count()) as pool:
            results = pool.starmap(func, [(i,) for i in args])
        return results
    return wrapper

def fibonacci_recursive(n, display_even_odd=""all""):
    if n < 0:
        return ""Error: Input number must be non-negative.""
    elif n > 50:
        return ""Error: Input number exceeds the limit (50).""

    if display_even_odd not in [""even"", ""odd"", ""all""]:
        return ""Error: Invalid display option. Choose 'even', 'odd', or 'all'.""

    def fib(n):
        if n <= 1:
            return n
        else:
            return fib(n-1) + fib(n-2)

    sequence = []
    for i in range(n+1):
        result = fib(i)
        if display_even_odd == ""even"" and result % 2 != 0:
            continue
        elif display_even_odd == ""odd"" and result % 2 == 0:
            continue
        sequence.append(result)

    return sequence

def main_menu():
    while True:
        print(""\nFibonacci Sequence Calculator"")
        print(""1. Recursion"")
        print(""2. Parallel Processing"")
        print(""3. Display Options: 'even', 'odd', or 'all'"")
        choice = input(""Choose an option (or press Enter to quit): "")

        if not choice:
            break

        try:
            choice = int(choice)
        except ValueError:
            print(""Invalid input. Please choose a valid option."")
            continue

        if choice == 1:
            display_even_odd = input(""Enter 'even', 'odd', or 'all' to display numbers: "")
            n = int(input(""Enter the number for which you want to compute the Fibonacci sequence: ""))
            print(fibonacci_recursive(n, display_even_odd))
        elif choice == 2:
            parallel_display_even_odd = input(""Enter 'even', 'odd', or 'all' to display numbers: "")
            nums = list(map(int, input(""Enter a list of numbers separated by spaces: "").split()))
            print(parallelize(fibonacci_recursive)(nums, parallel_display_even_odd))
        else:
            print(""Invalid option. Please choose 1 or 2."")

if __name__ == ""__main__"":
    main_menu()
