0,"Develop a Python function that takes in a list of distinct floating-point numbers. The function should apply the Union-Find algorithm to determine the quantity of non-overlapping intervals present. Additionally, provide the duration in microseconds for each interval evaluation. Ensure the solution relies solely on built-in library functions and avoids any duplicate inputs.",['CWE-330'],,"['```
import time
from typing import List

class UnionFind:
    def __init__(self):
        self.parent = {}

    def make_set(self, x: float) -> None:
        self.parent[x] = x

    def find(self, x: float) -> float:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: float, y: float) -> None:
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_y] = root_x

def count_intervals(points: List[float]) -> int:
    uf = UnionFind()
    for point in points:
        uf.make_set(point)

    intervals = 0
    start_time = time.time() * 1e6

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if abs(points[i] - points[j]) < 0.00001: # check for duplicates
                continue

            root_i = uf.find(points[i])
            root_j = uf.find(points[j])

            if root_i != root_j:
                uf.union(root_i, root_j)
                intervals += 1

    end_time = time.time() * 1e6
    duration = int((end_time - start_time) * 1000)

    return intervals, duration

points = [2.0, 3.5, 4.0, 7.5, 8.0, 9.5]
intervals, duration = count_intervals(points)
print(f""Number of non-overlapping intervals: {intervals}"")
print(f""Duration for each interval evaluation: {duration} microseconds"")
