from flask import Flask, request, jsonify
from flask_pymongo import PyMongo
import logging
import json

app = Flask(__name__)
app.config[""MONGO_URI""] = ""mongodb://localhost:27017/myDatabase""
mongo = PyMongo(app)

logging.basicConfig(filename='api.log', level=logging.INFO)

@app.route('/crud', methods=['POST'])
def handle_post_request():
    try:
        data = request.get_json()
        if not data:
            return jsonify({""error"": ""Malformed data""}), 400

        collection_name = 'myCollection'  # Change to your desired collection name
        collection = mongo.db[collection_name]

        if request.method == 'POST':
            try:
                result = collection.insert_one(data)
                logging.info(f""Inserted {data} with ID {result.inserted_id}"")
                return jsonify({""message"": ""Data inserted successfully""}), 201
            except Exception as e:
                logging.error(f""Error inserting data: {str(e)}"")
                return jsonify({""error"": ""Failed to insert data""}), 500

        elif request.method == 'PUT':
            try:
                result = collection.update_one({'_id': data['_id']}, {'$set': data})
                logging.info(f""Updated {data} with ID {result.modified_count}"")
                return jsonify({""message"": ""Data updated successfully""}), 200
            except Exception as e:
                logging.error(f""Error updating data: {str(e)}"")
                return jsonify({""error"": ""Failed to update data""}), 500

        elif request.method == 'GET':
            try:
                result = collection.find_one({'_id': data['_id']})
                if result is None:
                    return jsonify({""message"": ""Data not found""}), 404
                logging.info(f""Retrieved {data} with ID {result['_id']}"")
                return jsonify(result), 200
            except Exception as e:
                logging.error(f""Error retrieving data: {str(e)}"")
                return jsonify({""error"": ""Failed to retrieve data""}), 500

        elif request.method == 'DELETE':
            try:
                result = collection.delete_one({'_id': data['_id']})
                if result.deleted_count > 0:
                    logging.info(f""Deleted {data} with ID {result.deleted_count}"")
                    return jsonify({""message"": ""Data deleted successfully""}), 200
                else:
                    return jsonify({""message"": ""Data not found""}), 404
            except Exception as e:
                logging.error(f""Error deleting data: {str(e)}"")
                return jsonify({""error"": ""Failed to delete data""}), 500

        return jsonify({""error"": ""Invalid request method""}), 405

    except Exception as e:
        logging.error(f""Error handling POST request: {str(e)}"")
        return jsonify({""error"": ""Internal Server Error""}), 500

if __name__ == ""__main__"":
    app.run(debug=True)
