import argparse
import os
import sys

def parse_options():
    parser = argparse.ArgumentParser(description=""Text File Word Counter"")
    parser.add_argument(""filename"", help=""Specify the text file to process"")
    parser.add_argument(""--output"", ""-o"", help=""Write word count to specified file"")
    parser.add_argument(""--verbose"", ""-v"", action=""store_true"", help=""Display word count in the console"")
