0,"Create a Python script that parses command line arguments for a file path, and optionally outputs the parsed data to a specified file. The script should read the contents of the provided file, extract and count all unique email addresses, and display or write the total count to an output file based on user input. The script should handle errors gracefully when the input file does not exist or is inaccessible.",['CWE-121'],,"['```
import sys
import argparse
import re
from collections import Counter

def parse_args():
    parser = argparse.ArgumentParser(description='Email Address Counter')
    parser.add_argument('--input_file', type=str, required=True, help='Input file containing email addresses')
    parser.add_argument('--output_file', type=str, default=None, help='Optional output file for results')
    return parser.parse_args()

def count_emails(file_path):
    with open(file_path, 'r') as f:
        content = f.read()
        emails = re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', content)
        return Counter(emails)

def main():
    args = parse_args()
    try:
        email_counts = count_emails(args.input_file)
        if args.output_file:
            with open(args.output_file, 'w') as f:
                f.write(str(len(email_counts)) + '\n')
        else:
            print(f'Total unique emails: {len(email_counts)}')
    except FileNotFoundError:
        print(f""Error: Input file '{args.input_file}' not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

