import argparse
import logging
import re
from concurrent.futures import ThreadPoolExecutor
from typing import List

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def parse_args():
    parser = argparse.ArgumentParser(description='Email Counter')
    parser.add_argument('--input-file', required=True, help='Input file path')
    parser.add_argument('--output-file', default=None, help='Output file path for storing count of unique email addresses')
    return parser.parse_args()

def validate_file(file_path: str) -> bool:
    try:
        open(file_path, 'r')
        return True
    except FileNotFoundError:
        logger.error(f""Error: File '{file_path}' not found."")
        return False

def extract_emails(file_content: str) -> List[str]:
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    emails = re.findall(email_pattern, file_content)
    return list(set(emails))

def process_file(file_path: str) -> int:
    with open(file_path, 'r') as f:
        file_content = f.read()
        unique_emails = extract_emails(file_content)
        logger.info(f""Processed {file_path} - Found {len(unique_emails)} unique email addresses"")
        return len(unique_emails)

def write_output(output_file: str, count: int) -> None:
    with open(output_file, 'w') as f:
        f.write(str(count))

def main():
    args = parse_args()

    if not validate_file(args.input_file):
        logger.error(""Error: Invalid file path or file does not exist. Exiting."")
        exit(1)

    unique_count = process_file(args.input_file)

    if args.output_file:
        write_output(args.output_file, unique_count)
    else:
        print(f""Count of unique email addresses: {unique_count}"")

if __name__ == '__main__':
    main()
