class JSONHandler:
    def __init__(self):
        self.registry = {}

    def add_factory(self, factory_id, factory_function):
        if not callable(factory_function):
            raise ValueError(""factory_function must be a callable"")
        self.registry[factory_id] = factory_function

    def create_instance(self, json_string, factory_id):
        data = json.loads(json_string)
        if factory_id not in self.registry:
            raise ValueError(f""Factory function with ID {factory_id} not found"")
        return self.registry[factory_id](data)

